static class TodoEndpoints
{
    public static void MapTodoEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/todos")
            .WithTags("Todos")
            .AddEndpointFilter(async (ctx, next) =>           // runs for every endpoint
            {
                var req = ctx.HttpContext.Request;
                ctx.HttpContext.Response.Headers["X-Audit"] = $"{req.Method} {req.Path}";
                return await next(ctx);
            });

        group.MapGet("/{id:int}", (int id) => $"todo {id}")
             .AddEndpointFilter(async (ctx, next) =>          // validates one argument
                 ctx.GetArgument<int>(0) <= 0
                     ? TypedResults.Problem("id must be positive", statusCode: 400)
                     : await next(ctx));
    }
}

using System.Threading.RateLimiting;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddOutputCache();
builder.Services.AddRateLimiter(o =>
{
    o.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    o.AddPolicy("per-ip", ctx => RateLimitPartition.GetFixedWindowLimiter(
        ctx.Connection.RemoteIpAddress?.ToString() ?? "unknown",
        _ => new FixedWindowRateLimiterOptions { PermitLimit = 3, Window = TimeSpan.FromSeconds(10) }));
});
var app = builder.Build();
app.UseRateLimiter();
app.UseOutputCache();

app.MapGet("/time", () => DateTime.UtcNow.ToString("O"))
   .CacheOutput(p => p.Expire(TimeSpan.FromSeconds(5)).Tag("time"));
app.MapGet("/search", (string q) => $"results for {q}")
   .RequireRateLimiting("per-ip");
app.Run();
// GET /time twice within 5 s -> same timestamp (served from cache)
