static async IAsyncEnumerable<Todo> Stream(int n)
{
    for (int i = 1; i <= n; i++)
    {
        if (i % 100 == 0) await Task.Yield();       // e.g. awaiting DB pages
        yield return new Todo(i, $"Todo {i}", i % 2 == 0);
    }
}

